        crate::theme::init(cx);
        for mode in [ThemeMode::Dark, ThemeMode::Light] {
            Theme::change(mode, None, cx);
            for (ix, tab) in super::TABS.into_iter().enumerate() {
                let tint = super::mode_tint(tab, cx);
