                                (ask.center().x.as_f32() * scale) as usize,
                            );
                            let differs = (bottom.saturating_sub(4)..(bottom + 2).min(rows))
                                .any(|y| pixels[y * width + chain_x] != pixels[y * width + ask_x]);
